<?php
declare(strict_types=1);
namespace Namira;
use PDO;
/** Only profiles created by approval of a new application grant self-service rights. */
final class ArtistMemberships {
 public static function lock(PDO $db):string{return $db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';}
 public static function admin(PDO $db,array $actor,string $permission):array {$actor=CommunityHistory::requireActor($db,$actor);if(!Permissions::allows($db,$actor,$permission))throw new HttpError(403,'مجوز رسیدگی به این درخواست را ندارید.');ArtistPortalSchema::requireReady($db);return $actor;}
 public static function get(PDO $db,int $user):array|false {if(!ArtistPortalSchema::ready($db))return false;$r=Db::query($db,'SELECT * FROM artist_join_requests WHERE user_id=?',[$user])->fetch();if($r)$r['data']=Protocol::decode($r['payload']);return $r;}
 public static function approved(PDO $db,int $user):int {if(!ArtistPortalSchema::ready($db))return 0;return (int)Db::query($db,"SELECT j.artist_id FROM artist_join_requests j JOIN users u ON u.id=j.user_id JOIN artists a ON a.id=j.artist_id JOIN artist_accounts x ON x.artist_id=j.artist_id AND x.user_id=j.user_id LEFT JOIN artist_account_states s ON s.artist_id=x.artist_id AND s.user_id=x.user_id WHERE j.user_id=? AND j.status='approved' AND u.active=1 AND a.archived=0 AND COALESCE(s.active,1)=1",[$user])->fetchColumn();}
 public static function requireArtist(PDO $db,array $actor):array {$actor=MemberServices::requireMember($db,$actor);ArtistPortalSchema::requireReady($db);$id=self::approved($db,(int)$actor['id']);if(!$id)throw new HttpError(403,'حساب هنری تأییدشده و فعال لازم است.');return [$actor,$id];}
 public static function profileInput(PDO $db,array $in):array {
  $data=[];foreach(['first_name'=>150,'last_name'=>150,'art_name'=>255,'summary'=>2000,'biography'=>20000,'awards'=>10000,'private_phone'=>100,'private_email'=>190,'website'=>1000,'sample_links'=>5000,'contact_details'=>3000,'social_links'=>5000] as $key=>$max)$data[$key]=Security::text($in,$key,$max,in_array($key,['first_name','last_name','biography'],true));
  if($data['private_phone']===''&&$data['private_email']===''&&$data['contact_details']==='')throw new HttpError(422,'یک راه تماس خصوصی برای بررسی وارد کنید.');
  if($data['private_email']!==''&&!filter_var($data['private_email'],FILTER_VALIDATE_EMAIL))throw new HttpError(422,'ایمیل تماس معتبر نیست.');
  foreach(['website','sample_links','social_links'] as $key){$links=$key==='website'?[$data[$key]]:preg_split('/\R/u',$data[$key],-1,PREG_SPLIT_NO_EMPTY);foreach($links as $link)if($link!==''&&(!filter_var(trim($link),FILTER_VALIDATE_URL)||!in_array(parse_url(trim($link),PHP_URL_SCHEME),['http','https'],true)))throw new HttpError(422,'نشانی وب‌سایت، شبکه اجتماعی یا نمونه‌کار معتبر نیست.');}
  $terms=$in['specialties']??[];if(!is_array($terms)||!$terms||count($terms)>20)throw new HttpError(422,'حداقل یک حوزه فعالیت هنری انتخاب کنید.');$data['specialties']=[];foreach($terms as $term){if(!is_scalar($term)||!ctype_digit((string)$term)||!Db::query($db,"SELECT id FROM protocol_terms WHERE id=? AND taxonomy='art_specialty' AND active=1",[(int)$term])->fetchColumn())throw new HttpError(422,'حوزه هنری معتبر نیست.');$data['specialties'][]=(int)$term;}$data['specialties']=array_values(array_unique($data['specialties']));return $data;
 }
 public static function apply(PDO $db,array $actor,array $in,?string $avatar=null,array $samples=[]):int {
  $actor=MemberServices::requireMember($db,$actor);ArtistPortalSchema::requireReady($db);Security::limit($db,'artist-application',10,3600);$data=self::profileInput($db,$in);if(count($samples)>3)throw new HttpError(422,'حداکثر سه نمونه‌کار تصویری بفرستید.');$assets=[];$avatarSaved=null;
  try{return Db::transaction($db,function()use($db,$actor,$in,$data,$avatar,$samples,&$assets,&$avatarSaved){
   Db::query($db,'SELECT id FROM users WHERE id=?'.self::lock($db),[$actor['id']])->fetch();$old=self::get($db,(int)$actor['id']);if($old&&!in_array($old['status'],['rejected','needs_changes'],true))throw new HttpError(409,'درخواست قبلی شما فعال یا در حال بررسی است.');if($old&&(int)$old['revision']!==(int)($in['revision']??-1))throw new HttpError(409,'نسخه درخواست تغییر کرده است.');
   $avatarId=$old['avatar_asset_id']??null;if($avatar){$avatarSaved=Assets::put($db,$avatar,(int)$actor['id']);$avatarId=$avatarSaved['id'];}if(!$avatarId)throw new HttpError(422,'تصویر پروفایل انتخاب کنید.');$payload=$data;$payload['samples']=$old['data']['samples']??[];foreach($samples as $source){$asset=IncomingAssets::save($db,(int)$actor['id'],$source);$assets[]=$asset;$payload['samples'][]=$asset['id'];}if(count($payload['samples'])>6)throw new HttpError(422,'حداکثر شش نمونه‌کار در پرونده قابل نگهداری است.');if(!$payload['samples']&&$payload['sample_links']==='')throw new HttpError(422,'نمونه‌کار یا لینک نمونه‌کار وارد کنید.');$now=date('Y-m-d H:i:s');
   if($old){$id=(int)$old['id'];Db::query($db,"UPDATE artist_join_requests SET payload=?,avatar_asset_id=?,status='pending',revision=revision+1,review_note='',updated_at=? WHERE id=?",[Protocol::encode($payload),$avatarId,$now,$id]);}
   else $id=Db::insert($db,'artist_join_requests',['user_id'=>$actor['id'],'payload'=>Protocol::encode($payload),'avatar_asset_id'=>$avatarId,'review_note'=>'','created_at'=>$now,'updated_at'=>$now]);
   CommunityHistory::add($db,'artist_membership',$id,$actor,$old['status']??'','pending','درخواست ساخت پروفایل جدید');return $id;
  });}catch(\Throwable $e){IncomingAssets::discard($assets);if($avatarSaved)IncomingAssets::discardPaths([$avatarSaved['path']]);throw $e;}
 }
 public static function review(PDO $db,array $actor,int $id,array $in):int {
  $actor=self::admin($db,$actor,'artists.membership.review');$status=Security::text($in,'status',30);$note=Security::text($in,'note',5000,in_array($status,['rejected','needs_changes','suspended'],true));if(!in_array($status,['approved','rejected','needs_changes','suspended'],true))throw new HttpError(422,'نتیجه بررسی معتبر نیست.');
  return Db::transaction($db,function()use($db,$actor,$id,$in,$status,$note){$j=Db::query($db,'SELECT * FROM artist_join_requests WHERE id=?'.self::lock($db),[$id])->fetch();if(!$j)throw new HttpError(404,'درخواست پیدا نشد.');if((int)$j['revision']!==(int)($in['revision']??-1))throw new HttpError(409,'نسخه درخواست تغییر کرده است.');if(!in_array($j['status'],['pending','approved','suspended'],true)||($j['status']!=='pending'&&!in_array($status,['approved','suspended'],true)))throw new HttpError(409,'درخواست در وضعیت قابل بررسی نیست.');
   $artist=(int)$j['artist_id'];$now=date('Y-m-d H:i:s');if($status==='approved'){
    if(!Db::query($db,'SELECT id FROM users WHERE id=? AND active=1',[$j['user_id']])->fetchColumn())throw new HttpError(409,'حساب متقاضی غیرفعال است.');
    if(!$artist){$d=Protocol::decode($j['payload']);$profile=array_intersect_key($d,Artists::definitions());$profile['social_links']=$d['social_links'];$artist=(new Artists($db,$actor))->save(['data'=>$profile,'public_fields'=>['summary','biography','awards','website','social_links','specialties']]);Db::query($db,'UPDATE artists SET avatar_asset_id=? WHERE id=?',[$j['avatar_asset_id'],$artist]);AdminPublishing::artist($db,$actor,$artist);Db::insert($db,'artist_accounts',['artist_id'=>$artist,'user_id'=>$j['user_id'],'verified_by'=>$actor['id'],'verified_at'=>$now]);Db::insert($db,'artist_account_states',['artist_id'=>$artist,'user_id'=>$j['user_id'],'active'=>1,'reason'=>'پروفایل تازه از درخواست عضویت','updated_by'=>$actor['id'],'updated_at'=>$now]);}
    if(!Db::query($db,'SELECT user_id FROM user_roles WHERE user_id=? AND role_key=?',[$j['user_id'],'artist'])->fetchColumn())Db::insert($db,'user_roles',['user_id'=>$j['user_id'],'role_key'=>'artist']);
    Db::query($db,"UPDATE users SET role='artist' WHERE id=? AND role='member'",[$j['user_id']]);
   }elseif($status==='suspended'&&!$artist)throw new HttpError(422,'پروفایل تأییدشده‌ای برای تعلیق وجود ندارد.');
   if($artist)Db::query($db,'UPDATE artist_account_states SET active=?,reason=?,updated_by=?,updated_at=? WHERE artist_id=? AND user_id=?',[$status==='approved'?1:0,$note,$actor['id'],$now,$artist,$j['user_id']]);
   Db::query($db,'UPDATE artist_join_requests SET artist_id=?,status=?,review_note=?,reviewed_by=?,revision=revision+1,updated_at=? WHERE id=?',[$artist?:null,$status,$note,$actor['id'],$now,$id]);CommunityHistory::add($db,'artist_membership',$id,$actor,$j['status'],$status,$note);return $artist;
  });
 }
 public static function saveProfile(PDO $db,array $actor,array $in,?string $avatar=null):void {Security::limit($db,'artist-profile',20,3600);[$actor,$artist]=self::requireArtist($db,$actor);$d=self::profileInput($db,$in);unset($d['sample_links'],$d['contact_details']);$service=new Artists($db,$actor);$service->save(['data'=>$d,'revision'=>$in['revision']??-1],$artist,$avatar);$a=$service->get($artist);if(in_array($a['status'],['draft','published','needs_changes'],true))$service->transition($artist,'pending',['revision'=>$a['revision']]);CommunityHistory::add($db,'artist_profile',$artist,$actor,'saved','pending','تغییرات عمومی تا انتشار مدیر محفوظ می‌مانند.');}
}
